273	
274	    const tempQuaternion = new THREE.Quaternion();
275	
276	    const baseForward = new THREE.Vector3(0, 0, -1);
277	    const tempForward = new THREE.Vector3();
278	    const tempUp = new THREE.Vector3();
279	
280	    const tempRotationMatrix = new THREE.Matrix4();
281	    const tempTranslationMatrix = new THREE.Matrix4();
282	
283	    const currentTargetPosition = new THREE.Vector3();
284	    const lastTargetPosition = new THREE.Vector3();
285	
286	    const currentDirection = new THREE.Vector3();
287	    const lastDirection = new THREE.Vector3();
288	
289	    const lastRotationMatrix = new THREE.Matrix4();
290	
291	    return function updateTrailTarget(time) {
292	
293	        trail.update();
294	
295	        tempRotationMatrix.identity();
296	        tempTranslationMatrix.identity();
297	
298	        const scaledTime = time * .001;
299	        const areaScale = 100;
300	
301	        lastTargetPosition.copy(currentTargetPosition);
302	
303	        currentTargetPosition.x = Math.sin(scaledTime) * areaScale;
304	        currentTargetPosition.y = Math.sin(scaledTime * 1.1) * areaScale;
305	        currentTargetPosition.z = Math.sin(scaledTime * 1.6) * areaScale;
306	
307	        currentDirection.copy(currentTargetPosition);
308	        currentDirection.sub(lastTargetPosition);
309	        if (currentDirection.lengthSq() < .001) {
310	            currentDirection.copy(lastDirection);
311	        } else {
312	            currentDirection.normalize();
313	        }
314	
315	        tempUp.crossVectors(currentDirection, baseForward);
316	        const angle = baseForward.angleTo(currentDirection);
317	
318	        if(Math.abs(angle) > .01 && tempUp.lengthSq() > .001) {
319	            tempQuaternion.setFromUnitVectors(baseForward, currentDirection);
320	            tempQuaternion.normalize();
321	            tempRotationMatrix.makeRotationFromQuaternion(tempQuaternion);
322	            lastRotationMatrix.copy(tempRotationMatrix);
323	        }
324	        
325	        tempTranslationMatrix.makeTranslation (currentTargetPosition.x, currentTargetPosition.y, currentTargetPosition.z);
326	        tempTranslationMatrix.multiply(tempRotationMatrix);  
327	
328	        trailTarget.matrix.identity();
329	        trailTarget.applyMatrix4(tempTranslationMatrix);
330	        trailTarget.updateMatrixWorld();
331	
332	        lastDirection.copy(currentDirection);
333	    }
334	
335	}();
