399	function update() {
400	    const currentTime = performance.now();
401	    const deltaTime = lastFrameTime ? currentTime - lastFrameTime : 0;
402	    if (!options.pauseSim){
403	        elapsedSimTime += deltaTime;
404	        updateTrailTarget(elapsedSimTime);
405	    }
406	    lastFrameTime = currentTime;
407	    controls.update();
408	    stats.update();
409	}
