510	            returnObj.attribute = indices;
511	            returnObj.offset = srcNodeIndex * this.FacesPerNode * TrailRenderer.IndicesPerFace;
512	            returnObj.count = this.FacesPerNode * TrailRenderer.IndicesPerFace;
