                    "}",
                    "vUV = vec2(s, t); ",
                    "gl_Position = projectionMatrix * viewMatrix * realPosition;",
                "}"
            ].join("\n");
        },

        get TexturedFragmentShader() {
            return [
                this.TexturedFragmentVars,
                "void main() { ",
                    "vec4 textureColor = texture2D(trailTexture, vUV);",
